/* eslint-disable @next/next/no-head-element */
"use client";

import React, { useEffect, useState } from "react";
import styles from "../../app/page.module.css";
import Footer from "@/app/components/Footer";
import Navbar from "@/app/components/Navbar";
import axios from "axios";
import secureLocalStorage from "react-secure-storage";

type LoginHistoryItem = {
  date: string;
  ip: string;
  location: string;
  device: string;
  status: string;
};

export default function ConnectHist() {
  const [history, setHistory] = useState<LoginHistoryItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchLoginHistory = async () => {
      try {
        const userToken = secureLocalStorage.getItem("userToken") as string | null;
        if (!userToken) {
          setLoading(false);
          return;
        }

        // Récupérer l'historique de connexion depuis Auth0 (exemple: user_metadata.login_history)
        const userInfoResponse = await axios.get(
          `${process.env.NEXT_PUBLIC_AUTH0_DOMAIN}/userinfo`,
          {
            headers: {
              Authorization: `Bearer ${userToken}`,
              "Content-Type": "application/json",
            },
          }
        );
        const userId = userInfoResponse.data.sub;

        const response = await axios.get(
          `${process.env.NEXT_PUBLIC_AUTH0_DOMAIN}/api/v2/users/${userId}`,
          {
            headers: {
              Authorization: `Bearer ${userToken}`,
              "Content-Type": "application/json",
            },
          }
        );

        // Exemple de récupération de l'historique depuis les métadonnées
        const loginHistory: LoginHistoryItem[] =
          response.data?.user_metadata?.login_history || [
            // Données factices si rien dans Auth0
            {
              date: "2025-09-20T08:12:34Z",
              ip: "192.168.1.12",
              location: "Paris, France",
              device: "Chrome Windows",
              status: "Succès",
            },
            {
              date: "2025-09-21T19:45:10Z",
              ip: "192.168.1.15",
              location: "Lyon, France",
              device: "Safari iPhone",
              status: "Succès",
            },
            {
              date: "2025-09-22T07:01:55Z",
              ip: "192.168.1.22",
              location: "Marseille, France",
              device: "Edge Windows",
              status: "Échec",
            },
          ];

        setHistory(loginHistory);
      } catch (error) {
        setHistory([]);
      } finally {
        setLoading(false);
      }
    };

    fetchLoginHistory();
  }, []);

  return (
    <div className={styles.container2}>
      <head>
        <title>Historique de connexions - Vyft program</title>
      </head>
      <Navbar />
      <main className={styles.main}>
        <h1 className={styles.headeronwhiteX2}>Historique de connexions</h1>
        <section
          className={styles.bodyonwhite}
          style={{
            background: "#fff",
            borderRadius: 24,
            padding: 32,
            marginBottom: 32,
            width: "100%",
            maxWidth: 700,
            boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
          }}
        >
          <h2 className={styles.headeronwhite} style={{ fontSize: 22, marginBottom: 18 }}>
            Dernières connexions
          </h2>
          {loading ? (
            <p className={styles.bodyonwhite}>Chargement...</p>
          ) : history.length === 0 ? (
            <p className={styles.bodyonwhite}>Aucune connexion trouvée.</p>
          ) : (
            <ul style={{ listStyle: "none", padding: 0 }}>
              {history.map((item, idx) => {
                const dateObj = new Date(item.date);
                const formattedDate = dateObj.toLocaleDateString("fr-FR", {
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                });
                const formattedTime = dateObj.toLocaleTimeString("fr-FR", {
                  hour: "2-digit",
                  minute: "2-digit",
                  second: "2-digit",
                });
                return (
                  <li
                    key={idx}
                    className={styles.bodyonwhite}
                    style={{
                      marginBottom: 18,
                      background: "#DBDFE0",
                      borderRadius: 18,
                      padding: 18,
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <div>
                      <h3
                        className={styles.headeronwhite}
                        style={{
                          fontSize: 20,
                          margin: 0,
                          fontWeight: "bold",
                          color: "#1a7f6b",
                        }}
                      >
                        {item.device}
                      </h3>
                      <p
                        className={styles.headeronwhite}
                        style={{
                          fontSize: 15,
                          margin: "4px 0 0 0",
                          fontWeight: 500,
                          color: "#444444",
                        }}
                      >
                        {formattedDate} à {formattedTime}
                      </p>
                      <p
                        className={styles.bodyonwhite}
                        style={{
                          fontSize: 14,
                          margin: "4px 0 0 0",
                          color: "#222",
                        }}
                      >
                        <b>IP :</b> {item.ip} — <b>Lieu :</b> {item.location} — <b>Statut :</b>{" "}
                        <span style={{ color: item.status === "Succès" ? "#1a7f6b" : "#d32f2f", fontWeight: "bold" }}>
                          {item.status}
                        </span>
                      </p>
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </section>
      </main>
      <Footer />
    </div>
  );
}